/*
 * This file was generated by the Gradle 'init' task.
 */

plugins {
    `java-library`
    `maven-publish`
    kotlin("jvm") version "2.2.0"
}

repositories {
    mavenLocal()
    maven {
        url = uri("https://jogamp.org/deployment/maven/")
        // BCU KR: only JOGL comes from here, so the other libraries don't depend on this server being reachable
        content { includeGroupByRegex("org\\.jogamp.*") }
    }

    maven {
        url = uri("https://repo.maven.apache.org/maven2/")
    }
    mavenCentral()
}

sourceSets {
    main {
        resources {
            srcDirs("src/main/java", "src/main/resources")
            exclude("**/*.java")
        }
    }
}

dependencies {
    api(libs.commons.codec.commons.codec)
    api(libs.commons.io.commons.io)
    api(libs.commons.logging.commons.logging)
    api(libs.org.apache.httpcomponents.httpclient)
    api(libs.org.apache.httpcomponents.httpcore)
    api(libs.org.apache.httpcomponents.httpmime)
    api(libs.org.jcodec.jcodec)
    api(libs.org.jcodec.jcodec.javase)
    api(libs.com.google.api.client.google.api.client)
    api(libs.com.google.http.client.google.http.client)
    api(libs.org.json.json)
    api(libs.com.googlecode.soundlibs.tritonus.share)
    api(libs.com.googlecode.soundlibs.vorbisspi)
    api(libs.org.jogamp.jogl.jogl.all)
    api(libs.org.jogamp.gluegen.gluegen.rt)
    api(libs.org.jogamp.jogl.jogl.all.main)
    api(libs.org.jogamp.gluegen.gluegen.rt.main)
    api(libs.com.google.apis.google.api.services.drive)
    api(libs.com.google.oauth.client.google.oauth.client.jetty)
    api(libs.com.google.code.gson.gson)
    api(libs.org.jetbrains.kotlin.kotlin.stdlib.jdk8)
    testImplementation(libs.org.jetbrains.kotlin.kotlin.test)
}

group = "com.battlecatsultimate"
version = "0.0.1-SNAPSHOT"
description = "BCU-java-PC"

publishing {
    publications.create<MavenPublication>("maven") {
        from(components["java"])
    }
}

tasks.withType<JavaCompile> {
    options.encoding = "UTF-8"
    options.release = 8
}

// (src/main/resources is listed in sourceSets on top of Gradle's default, so each resource comes twice: same file)
tasks.processResources {
    duplicatesStrategy = DuplicatesStrategy.EXCLUDE
}

tasks.withType<Javadoc> {
    options.encoding = "UTF-8"
}

kotlin {
    // Compiled with JDK 17 into Java 8 classes (Java's --release 8, Kotlin's jvmTarget 1.8), so BCU still runs on
    // Java 8. (Java 8's own compiler can't build the core: it has no --release flag and resolves some generic calls
    // in the core differently.)
    jvmToolchain(17)
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_1_8)
    }
}
// BCU KR: a ready-to-run zip: BCU-KR.jar (starts with a double-click or `java -jar BCU-KR.jar`), its libraries in
// lib/ and a short read-me. Official BCU is started by BCU-Initializer.jar instead, which downloads the official jar.
val bcuKrVersion = "0.5.8.8-kr1" // BCU PC 0.5.8.8 (MainBCU.ver 50808) + this copy's changes

tasks.jar {
    archiveFileName.set("BCU-KR.jar")
    val libs = configurations.runtimeClasspath.map { c -> c.files.joinToString(" ") { "lib/" + it.name } }
    manifest {
        attributes("Main-Class" to "main.MainBCU", "Class-Path" to libs)
    }
}

val bcuKrZip by tasks.registering(Zip::class) {
    group = "distribution"
    description = "Builds build/dist/BCU-KR-<version>.zip"
    archiveFileName.set("BCU-KR-$bcuKrVersion.zip")
    destinationDirectory.set(layout.buildDirectory.dir("dist"))
    into("BCU-KR") {
        from(tasks.jar)
        from(configurations.runtimeClasspath) { into("lib") }
        from("dist")
    }
}
